import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"00-1 从零认识智能合约：先别急着写代码","description":"","frontmatter":{},"headers":[],"relativePath":"00-start/index.md","filePath":"00-start/index.md","lastUpdated":1791601077000}'),e={name:"00-start/index.md"};function l(r,t,p,d,o,h){return s(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="_00-1-从零认识智能合约-先别急着写代码" tabindex="-1">00-1 从零认识智能合约：先别急着写代码 <a class="header-anchor" href="#_00-1-从零认识智能合约-先别急着写代码" aria-label="Permalink to &quot;00-1 从零认识智能合约：先别急着写代码&quot;">​</a></h1><blockquote><p><strong>适合谁</strong>：没接触过区块链，但会一点 Python、Web 开发或数据库的人。如果连 Python 也不会，本课的故事和操作仍能看懂。</p><p><strong>本课目标</strong>：读完后能用自己的话解释区块链、智能合约、账户、钱包、交易、Gas，并能分清“读数据”和“改数据”。<strong>本课不要求安装软件。</strong></p></blockquote><h2 id="先用一个生活场景理解" tabindex="-1">先用一个生活场景理解 <a class="header-anchor" href="#先用一个生活场景理解" aria-label="Permalink to &quot;先用一个生活场景理解&quot;">​</a></h2><p>假设你在网上买一台二手相机，售价 100 元。你担心付了款卖家不发货；卖家担心发了货你不付款。</p><p>传统的做法是找平台担保：</p><ol><li>买家先把 100 元交给平台。</li><li>平台记录“买家已付款”。</li><li>卖家发货。</li><li>买家确认收货。</li><li>平台把 100 元转给卖家。</li></ol><p>如果平台是一个 Flask 项目，流程可能是：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@app.post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/orders/&lt;order_id&gt;/confirm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> confirm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(order_id):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 省略：验证登录身份、订单归属、付款和发货状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    db.execute(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UPDATE orders SET status = &#39;COMPLETED&#39; WHERE id = ?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (order_id,))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pay_to_seller(order_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这里有一个前提：<strong>大家信任平台会按照约定执行规则</strong>。平台管理员能改数据库，服务器可能宕机，转账服务也可能失败。</p><p>智能合约提供另一种实现方式：<strong>把“谁能付款、谁能确认、什么情况下退款”写成程序，并部署到区块链上，由区块链网络按照同一套规则执行。</strong></p><p>注意：这不意味着区块链能知道相机是否真的发货，也不意味着合约天然没有漏洞。链下发生的现实事实，仍需要人、可信数据源或争议处理机制来判断。</p><h2 id="先弄懂-6-个必须知道的词" tabindex="-1">先弄懂 6 个必须知道的词 <a class="header-anchor" href="#先弄懂-6-个必须知道的词" aria-label="Permalink to &quot;先弄懂 6 个必须知道的词&quot;">​</a></h2><h3 id="_1-区块链-多人共同维护的账本" tabindex="-1">1. 区块链：多人共同维护的账本 <a class="header-anchor" href="#_1-区块链-多人共同维护的账本" aria-label="Permalink to &quot;1. 区块链：多人共同维护的账本&quot;">​</a></h3><p>把它想成<strong>许多计算机共同维护的一份账本</strong>，而不是你自己部署的一台 MySQL 服务器。它记录交易以及执行后形成的状态。不同链有不同规则，不能把所有区块链当成同一种系统。</p><ul><li>数据不是存在“你的钱包 APP 里”。</li><li>交易被网络接受并写入区块后，其他人可以验证相关记录。</li><li>已确认的记录通常不能像本地数据库那样由管理员直接改掉；但链可能出现重组，业务上仍要考虑确认状态。</li></ul><h3 id="_2-智能合约-部署在链上的程序" tabindex="-1">2. 智能合约：部署在链上的程序 <a class="header-anchor" href="#_2-智能合约-部署在链上的程序" aria-label="Permalink to &quot;2. 智能合约：部署在链上的程序&quot;">​</a></h3><p><strong>智能合约是程序，不是会思考的智能 AI，也不一定是法律合同。</strong></p><p>它更像一个带持久数据的后端模块：有函数，也有自己的状态，其他账户或合约可以根据网络规则调用它。</p><p>我们后面用 <strong>Solidity</strong> 编写源码，再将源码编译成能由 <strong>EVM（以太坊虚拟机）</strong> 执行的字节码。你可以先把 EVM 想成“执行这类程序的运行环境”，类似 Python 解释器的角色，但运行规则不同。</p><h3 id="_3-账户与地址-谁发起操作" tabindex="-1">3. 账户与地址：谁发起操作 <a class="header-anchor" href="#_3-账户与地址-谁发起操作" aria-label="Permalink to &quot;3. 账户与地址：谁发起操作&quot;">​</a></h3><p>可以把地址理解成一个公开的账户编号。一个常见的以太坊地址形如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0x1234567890abcdef1234567890abcdef12345678</span></span></code></pre></div><p>这是<strong>示例地址</strong>，不要往这里转账。地址不等于真实身份，也不等于网站用户名。</p><p>常见的两类账户：</p><ul><li><strong>外部账户（EOA）</strong>：通常由私钥控制，能发起交易。</li><li><strong>合约账户</strong>：地址对应链上代码和状态，响应调用。</li></ul><h3 id="_4-钱包-替你保管或使用密钥的工具" tabindex="-1">4. 钱包：替你保管或使用密钥的工具 <a class="header-anchor" href="#_4-钱包-替你保管或使用密钥的工具" aria-label="Permalink to &quot;4. 钱包：替你保管或使用密钥的工具&quot;">​</a></h3><p>钱包不是一个真的“装 ETH 的文件夹”。余额由链上状态反映；钱包负责管理密钥、查看余额、构造交易以及请求签名。</p><p>可以记住下面的关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>私钥（秘密） ──用于签名──&gt; 证明你授权了某笔交易</span></span>
<span class="line"><span>地址（公开） ────────────&gt; 其他人用来识别链上账户</span></span>
<span class="line"><span>钱包（工具） ────────────&gt; 帮你查看账户、发出签名请求</span></span></code></pre></div><p><strong>绝不能把真实私钥、助记词放进代码、截图、聊天或 Git。</strong> 本课程先使用 Remix 内置虚拟账户，不需要真实钱包。</p><h3 id="_5-交易-transaction-请求网络改变状态" tabindex="-1">5. 交易（Transaction）：请求网络改变状态 <a class="header-anchor" href="#_5-交易-transaction-请求网络改变状态" aria-label="Permalink to &quot;5. 交易（Transaction）：请求网络改变状态&quot;">​</a></h3><p>例如“计数器加 1”或“向合约付款”，通常要通过交易提交。</p><p>一笔典型的交易会经历：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击按钮</span></span>
<span class="line"><span>  → 钱包准备交易</span></span>
<span class="line"><span>  → 账户签名（证明授权）</span></span>
<span class="line"><span>  → RPC 节点接收并广播</span></span>
<span class="line"><span>  → 网络执行合约代码、记录结果</span></span>
<span class="line"><span>  → 交易被打包，应用读取回执确认结果</span></span></code></pre></div><p>这里 <strong>RPC 节点</strong> 就像访问区块链的网络接口。它不是“区块链的总管理员”，也不能替你决定合约的权限规则。</p><p><strong>发出交易 ≠ 交易执行成功</strong>。拿到交易哈希只能表示得到了一个标识，还要检查回执状态和所需确认程度。</p><h3 id="_6-gas-让链上执行有成本" tabindex="-1">6. Gas：让链上执行有成本 <a class="header-anchor" href="#_6-gas-让链上执行有成本" aria-label="Permalink to &quot;6. Gas：让链上执行有成本&quot;">​</a></h3><p>在传统 Flask 服务里，你可能为服务器付费；在以太坊这类链上，执行交易需要资源，系统用 <strong>Gas</strong> 计量。</p><p>用出租车类比：</p><ul><li><strong>Gas Used</strong>：实际消耗了多少“计量单位”，类似实际行驶里程。</li><li><strong>Gas Price</strong>：每个单位要付多少钱，类似每公里单价。</li><li><strong>Gas Limit</strong>：这次交易最多愿意提供多少计算资源，类似给行程设一个上限。</li></ul><p>粗略关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>交易执行费用 ≈ 实际 Gas Used × 实际有效 Gas Price</span></span></code></pre></div><p>但不同网络的收费结构可能不同，还可能涉及 L2 数据费用等。<strong>Gas 是计量单位，不直接等于 ETH，也不等于人民币。</strong></p><p>在 Remix VM 中使用的是<strong>虚拟测试余额</strong>，不会花真实资金。</p><h2 id="两种操作-看数据和改数据" tabindex="-1">两种操作：看数据和改数据 <a class="header-anchor" href="#两种操作-看数据和改数据" aria-label="Permalink to &quot;两种操作：看数据和改数据&quot;">​</a></h2><p>假设链上有一个计数器，当前数字是 0。</p><table tabindex="0"><thead><tr><th>你做的事情</th><th>类比 Flask</th><th>通常需要链上交易？</th><th>链上 Gas 费用？</th></tr></thead><tbody><tr><td>看现在数字是几</td><td>GET 查询</td><td>不需要</td><td>本地调用不向链支付</td></tr><tr><td>把数字加 1</td><td>POST 更新</td><td>需要</td><td>交易执行时通常产生</td></tr><tr><td>修改失败并回滚</td><td>业务校验失败</td><td>仍可能已提交交易</td><td>已使用的 Gas 通常仍付费</td></tr></tbody></table><p>注意，“只读免费”指典型的 <strong>链下 eth_call 不付链上费用</strong>，不代表提供 RPC 的服务商一定免费，也不代表 view 函数在链上被其他合约调用就没有计算成本。</p><h2 id="和你熟悉的后端-对照理解" tabindex="-1">和你熟悉的后端，对照理解 <a class="header-anchor" href="#和你熟悉的后端-对照理解" aria-label="Permalink to &quot;和你熟悉的后端，对照理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后端开发概念</th><th>链上类似概念</th><th>千万别误解</th></tr></thead><tbody><tr><td>Python 函数</td><td>Solidity 函数</td><td>写状态可能需要交易并消耗 Gas</td></tr><tr><td>数据库表/记录</td><td>合约状态变量、mapping</td><td>不是可任意 SQL 查询的数据库</td></tr><tr><td>用户登录信息</td><td>签名、调用者地址</td><td>地址不等于现实身份</td></tr><tr><td>API 请求</td><td>合约调用</td><td>写操作需要关注交易确认</td></tr><tr><td>数据库事务回滚</td><td>EVM 交易 revert</td><td>失败交易的已消耗 Gas 不自动退还</td></tr><tr><td>日志</td><td>合约 event</td><td>event 主要用于观察，不是当前业务状态</td></tr><tr><td>Celery / cron</td><td>外部触发交易</td><td>合约不会自己在指定时间醒来</td></tr></tbody></table><h2 id="不用安装任何东西-做三个小判断" tabindex="-1">不用安装任何东西，做三个小判断 <a class="header-anchor" href="#不用安装任何东西-做三个小判断" aria-label="Permalink to &quot;不用安装任何东西，做三个小判断&quot;">​</a></h2><p><strong>问题 1：</strong> 我把钱包 APP 卸载，链上的余额是不是就没了？</p><p><strong>问题 2：</strong> 我在 Remix 中点击“读取数字”和“数字加 1”，哪一个更像数据库 SELECT，哪一个更像 UPDATE？</p><p><strong>问题 3：</strong> 能不能把身份证号放在 Solidity 的 private 变量里，认为别人看不到？</p><details><summary>点开参考答案（先自己想一遍）</summary><ol><li>不是。链上的状态并不存放在 APP 里；但如果丢失了唯一的恢复方式，就可能无法再控制对应账户。</li><li>读取类似 SELECT；加 1 类似 UPDATE。不过链上写入的签名、执行、收费和确认机制与数据库不同。</li><li>不能。Solidity 的 private 限制合约代码内的访问方式，不是加密；链上数据可能被外部观察。</li></ol></details><h2 id="下一步与本课验收" tabindex="-1">下一步与本课验收 <a class="header-anchor" href="#下一步与本课验收" aria-label="Permalink to &quot;下一步与本课验收&quot;">​</a></h2><p>你能向别人解释“钱包不装钱”“Gas 不等于手续费的法币金额”“智能合约不能自动知道现实世界发货状态”，就可以继续。</p><ul><li><a href="/00-start/environment">下一课：像跟着截图一样使用 Remix，部署第一个合约</a></li><li><a href="/00-start/glossary">随时查：零基础术语词典</a></li></ul><blockquote><p><strong>安全约定</strong>：课程所有资金、账户和合约实验先使用本地虚拟链；示例代码不能直接用于管理真钱。</p></blockquote>`,59)])])}const k=a(e,[["render",l]]);export{g as __pageData,k as default};
